using System.Collections.Generic;
using System.Linq;
using System.Net;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestHelper.CreateInMemoryContext();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        #region Index

        [Fact]
        public void Index_NoParams_ReturnsViewWithInstructorIndexData()
        {
            TestHelper.SeedCourses(_context); // seeds instructors + departments + courses

            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Instructors);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            TestHelper.SeedCourses(_context);
            var instructor = _context.Instructors.First();
            // Add a course assignment
            _context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = _context.Courses.First().CourseID
            });
            _context.SaveChanges();

            var result = _controller.Index(instructor.ID, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal((object)instructor.ID, _controller.ViewBag.InstructorID);
        }

        [Fact]
        public void Index_InstructorsOrderedByLastName()
        {
            TestHelper.SeedCourses(_context);

            var result = _controller.Index(null, null) as ViewResult;

            var model = Assert.IsType<InstructorIndexData>(result!.Model);
            var instructors = model.Instructors.ToList();
            Assert.Equal("Abercrombie", instructors[0].LastName);
            Assert.Equal("Fakhouri", instructors[1].LastName);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            var result = _controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            TestHelper.SeedInstructors(_context);
            var instructor = _context.Instructors.First();

            var result = _controller.Details(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.ID, model.ID);
            Assert.Equal(instructor.LastName, model.LastName);
            Assert.Equal(instructor.FirstMidName, model.FirstMidName);
        }

        #endregion

        #region Create GET

        [Fact]
        public void Create_Get_ReturnsViewWithInstructorAndCoursesViewBag()
        {
            TestHelper.SeedCourses(_context);

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.Empty(model.CourseAssignments);
            Assert.NotNull(_controller.ViewBag.Courses);
            var coursesViewBag = Assert.IsAssignableFrom<List<AssignedCourseData>>(_controller.ViewBag.Courses);
            Assert.Equal(2, coursesViewBag.Count);
        }

        #endregion

        #region Create POST

        [Fact]
        public void Create_Post_ValidInstructor_NoSelectedCourses_AddsAndRedirects()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = DateTime.Parse("2020-01-15"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(1, _context.Instructors.Count());
            var saved = _context.Instructors.First();
            Assert.Equal("Jane", saved.FirstMidName);
            Assert.Equal("Doe", saved.LastName);
            Assert.Equal(DateTime.Parse("2020-01-15"), saved.HireDate);
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_CreatesCourseAssignments()
        {
            TestHelper.SeedCourses(_context);
            var course = _context.Courses.First();
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = DateTime.Parse("2020-01-15"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, new[] { course.CourseID.ToString() });

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Instructors.First(i => i.LastName == "Doe");
            Assert.Single(_context.CourseAssignments.Where(ca => ca.InstructorID == saved.ID));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsViewWithCoursesViewBag()
        {
            TestHelper.SeedCourses(_context);
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "",
                HireDate = DateTime.Parse("2020-01-15"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null) as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        #endregion

        #region Edit GET

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            Assert.IsType<StatusCodeResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithInstructorAndCoursesData()
        {
            TestHelper.SeedCourses(_context);
            var instructor = _context.Instructors.First();

            var result = _controller.Edit(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.ID, model.ID);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        #endregion

        #region Delete GET

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            Assert.IsType<StatusCodeResult>(result);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithInstructor()
        {
            TestHelper.SeedInstructors(_context);
            var instructor = _context.Instructors.First();

            var result = _controller.Delete(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.ID, model.ID);
        }

        #endregion

        #region DeleteConfirmed

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            TestHelper.SeedCourses(_context); // seeds instructors + depts
            var instructor = _context.Instructors.First();
            var initialCount = _context.Instructors.Count();

            var result = _controller.DeleteConfirmed(instructor.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(initialCount - 1, _context.Instructors.Count());
        }

        [Fact]
        public void DeleteConfirmed_InstructorIsAdministrator_NullsDepartmentAdministrator()
        {
            TestHelper.SeedDepartments(_context);
            var dept = _context.Departments.First(d => d.InstructorID != null);
            var instructorId = dept.InstructorID!.Value;

            _controller.DeleteConfirmed(instructorId);

            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.Null(updatedDept!.InstructorID);
        }

        #endregion
    }
}

using ContosoUniversity.Controllers;
