namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        public HomeControllerTests()
        {
            _context = TestHelper.CreateInMemoryContext();
            _controller = new HomeController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void About_ReturnsViewWithEnrollmentDateGroups()
        {
            TestHelper.SeedStudents(_context);

            var result = _controller.About() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
            Assert.NotEmpty(model);
            Assert.All(model, g => Assert.True(g.StudentCount > 0));
        }

        [Fact]
        public void About_GroupsStudentsByEnrollmentDate()
        {
            // Add students with same date
            _context.Students.AddRange(
                new Student { FirstMidName = "A", LastName = "One", EnrollmentDate = DateTime.Parse("2020-09-01") },
                new Student { FirstMidName = "B", LastName = "Two", EnrollmentDate = DateTime.Parse("2020-09-01") },
                new Student { FirstMidName = "C", LastName = "Three", EnrollmentDate = DateTime.Parse("2021-09-01") }
            );
            _context.SaveChanges();

            var result = _controller.About() as ViewResult;

            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result!.Model);
            Assert.Equal(2, model.Count);
            var group2020 = model.Single(g => g.EnrollmentDate == DateTime.Parse("2020-09-01"));
            Assert.Equal(2, group2020.StudentCount);
            var group2021 = model.Single(g => g.EnrollmentDate == DateTime.Parse("2021-09-01"));
            Assert.Equal(1, group2021.StudentCount);
        }

        [Fact]
        public void About_EmptyDb_ReturnsEmptyList()
        {
            var result = _controller.About() as ViewResult;

            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result!.Model);
            Assert.Empty(model);
        }

        [Fact]
        public void Contact_SetsViewBagMessage()
        {
            var result = _controller.Contact() as ViewResult;

            Assert.NotNull(result);
            Assert.Equal("Your contact page.", (string)_controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsViewResult()
        {
            var result = _controller.Error();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Unauthorized_SetsViewBagMessageAndReturnsView()
        {
            var result = _controller.Unauthorized() as ViewResult;

            Assert.NotNull(result);
            Assert.Equal("You don't have permission to access this resource.", (string)_controller.ViewBag.Message);
        }
    }
