+        public void Initialize_EmptyDatabase_SeedsInstructors()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+
+            Assert.Equal(5, context.Instructors.Count());
+            Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
+            Assert.Contains(context.Instructors, i => i.LastName == "Zheng");
+        }
+
+        [Fact]
+        public void Initialize_EmptyDatabase_SeedsDepartments()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+
+            Assert.Equal(4, context.Departments.Count());
+            Assert.Contains(context.Departments, d => d.Name == "English" && d.Budget == 350000);
+            Assert.Contains(context.Departments, d => d.Name == "Economics" && d.Budget == 100000);
+        }
+
+        [Fact]
+        public void Initialize_EmptyDatabase_SeedsCourses()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+
+            Assert.Equal(7, context.Courses.Count());
+            Assert.Contains(context.Courses, c => c.Title == "Chemistry" && c.Credits == 3);
+            Assert.Contains(context.Courses, c => c.Title == "Calculus" && c.Credits == 4);
+        }
+
+        [Fact]
+        public void Initialize_EmptyDatabase_SeedsEnrollments()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+
+            Assert.Equal(11, context.Enrollments.Count());
+        }
+
+        [Fact]
+        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+
+            Assert.Equal(3, context.OfficeAssignments.Count());
+            Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
+            Assert.Contains(context.OfficeAssignments, o => o.Location == "Thompson 304");
+        }
+
+        [Fact]
+        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+
+            Assert.Equal(8, context.CourseAssignments.Count());
+        }
+
+        [Fact]
+        public void Initialize_AlreadySeeded_DoesNotDuplicate()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+            var studentCount = context.Students.Count();
+            var courseCount = context.Courses.Count();
+
+            DbInitializer.Initialize(context);
+
+            Assert.Equal(studentCount, context.Students.Count());
+            Assert.Equal(courseCount, context.Courses.Count());
+        }
+
+        [Fact]
+        public void Initialize_EnrollmentsHaveGrades()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+
+            var gradedEnrollments = context.Enrollments.Where(e => e.Grade != null).ToList();
+            Assert.NotEmpty(gradedEnrollments);
+            Assert.Contains(gradedEnrollments, e => e.Grade == Grade.A);
+            Assert.Contains(gradedEnrollments, e => e.Grade == Grade.B);
+            Assert.Contains(gradedEnrollments, e => e.Grade == Grade.C);
+        }
+
+        [Fact]
+        public void Initialize_SomeEnrollmentsHaveNoGrade()
+        {
+            using var context = TestHelper.CreateInMemoryContext();
+
+            DbInitializer.Initialize(context);
+
+            var ungradedEnrollments = context.Enrollments.Where(e => e.Grade == null).ToList();
+            Assert.NotEmpty(ungradedEnrollments);
+        }
+    }
+}
